head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 2

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/mgt.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");
scwin.contnId;
scwin.objTpCd;
scwin.vCurDate;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDMGT42045.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_single_read = function() {
    //공지사항 개별조회

	//----W-Craft WebSquare 변환 확인: getContnId----//
    var getContnId = $c.frame.path("../").fn_getContnId;

	//----W-Craft WebSquare 변환 확인: getContnId----//
    var screnID = getContnId();
    trs_Read.Action = "/scren.do?method=readHelpContent&SCREN_ID=" + screnID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_NoticeContentSingle,O:pOutput2=dts_fileList)";

	//----W-Craft WebSquare 변환 확인: Post----//
    trs_Read.Post();
};
scwin.fn_update = function() {
    //공지사항 수정

    var rtn = confirm('위사항을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_NoticeContentSingle.setCellData(1, "NOTI_OBJ_SYS_TP_CD", $c.cp.valueOfIndex(cb_system_gbn, "VALUE", cb_system_gbn.getSelectedIndex()));
        var url1 = "/scren.do?method=modifyHelpContent" + "&SCREN_ID=" + scwin.vScrenID + "&V_SCREN_ID=" + scwin.contnId + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&FILE_NM=" + dts_fileList.getCellData(1, "filename");
        trs_Update.Action = encodeURI(url1);
        //trs_Update.Action="/scren.do?method=modifyHelpContent"+"&SCREN_ID=" + vScrenID+"&V_SCREN_ID=" + contnId;
        //trs_Update.KeyName="toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput1=dts_NoticeContentSingle,I:pFile1=dts_fileList)";

	//----W-Craft WebSquare 변환 확인: Post----//
        trs_Update.Post();
    }
};
scwin.fn_save = function() {
    //공지사항 등록
    if (cb_system_gbn.getSelectedIndex() <= 0) {
        alert("시스템을 선택하세요");
        cb_system_gbn.focus();
        return;
    }
    if (checkbox_1.checked) {
        ipt_scren_id.setValue(ipt_scren_id_2.getValue());
    }
    if (ipt_scren_id.getValue() == '') {
        alert("화면을 선택하세요");
        cmb_QuickMenu_scren.focus();
        return;
    }
    if (txb_ATTACH_FILE_NM.getValue() == '') {
        alert("첨부파일을 선택하세요");
        file.focus();
        return;
    }
    var url1 = "/scren.do?method=helpNoticeContent" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&FILE_NM=" + dts_fileList.getCellData(1, "filename");
    trs_Save.Action = encodeURI(url1);
    trs_Save.KeyValue = "JSP(I:pInput=dts_noticeInfo,I:pFile1=dts_fileList)";
    //dts_noticeInfo.NameValue(1,"NOTI_OBJ_SYS_TP_CD") = cb_system_gbn.ValueOfIndex("VALUE", cb_system_gbn.Index);
    dts_noticeInfo.setCellData(1, "NOTI_OBJ_SYS_TP_CD", MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL"));

	//----W-Craft WebSquare 변환 확인: Post----//
    trs_Save.Post();
    dts_fileList.removeAll();
    dts_fileList.insertRow();
    setObjectValue(txb_ATTACH_FILE_NM, '');
};
scwin.fn_delete = function() {
    //공지사항 삭제

    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_NoticeDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_NoticeDelete.insertRow();
        dts_NoticeDelete.setCellData(1, "CONTN_ID", scwin.contnId);
        dts_NoticeDelete.setCellData(1, "NOTI_OBJ_SYS_TP_CD", scwin.objTpCd);

	//----W-Craft WebSquare 변환 확인: getContnId----//
        var getContnId = $c.frame.path("../").fn_getContnId;

	//----W-Craft WebSquare 변환 확인: getContnId----//
        var screnID = getContnId();
        trs_Delete.Action = "/scren.do?method=removeHelpContent" + "&SCREN_ID=" + screnID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_NoticeDelete)";

	//----W-Craft WebSquare 변환 확인: Post----//
        trs_Delete.Post();
    }
};
scwin.fn_SetIrInfoHeader = function() {
    // CUD용 Header
    dts_noticeInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=HELPCONTENT_INOUT";

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_noticeInfo.Reset();
    dts_noticeInfo.insertRow();
};

//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&gubun=35";
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval(getStringSize(obj.value) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_code1_sync = function() {
    var url1 = "/scren.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ENG_NM=NOTI_OBJ_SYS_TP_CD";
    MxDataSet_code1.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval(getStringSize(obj.text) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_SelectAttach = function() {
    if (scwin.contnId != "input") {
        dts_fileList.removeAll();
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileList.insertRow();
    }
    if (file.Value == "") return;
    txb_ATTACH_FILE_NM.setValue(file.Value);
    dts_fileList.setCellData(1, "fileInfo", file.Value);
    dts_fileList.setCellData(1, "fileUrl", file.Value);
    dts_fileList.setCellData(1, "filename", file.Value);
};




//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		

	//----W-Craft WebSquare 변환 확인: FileInfo----//
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};
scwin.fn_list_menu = function() {
    var cbSystemGbnValue = MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL");
    var url1 = "/topmenu.do?method=searchStfTopMenu&inputMessageId=topmenu&outputMessageId=topmenu&NOTI_OBJ_SYS_TP_CD=" + cbSystemGbnValue;
    dts_menu.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_menu.reset();
    topmenusearch.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    topmenusearch.reset();
};
scwin.fn_topmenusearchEnter = function() {
    // 2008-06-30
    //화면검색 엔터시

	//----W-Craft WebSquare 변환 확인: Filter----//
    topmenusearch.UseFilter = "true";

	//----W-Craft WebSquare 변환 확인: Filter----//
    topmenusearch.Filter();

	//----W-Craft WebSquare 변환 확인: ResetData----//

	//----W-Craft WebSquare 변환 확인: Reset----//
    cmb_QuickMenu_scren.ResetData();
    cmb_QuickMenu_scren.setSelectedIndex(-1);
    cmb_QuickMenu_scren.trigger("onclick");
};
scwin.btn_save_onclick = function() {
    if (scwin.contnId == "input") {
        scwin.fn_save();
    } else {
        scwin.fn_update();
    }
};
scwin.trs_Save_OnSuccess = async function() {
    alert(getMessageParam("MSG-A001", "도움말등록"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    alert(getMessageParam("MSG-A002", "도움말등록"));
    alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Update_OnSuccess = async function() {
    alert(getMessageParam("MSG-A001", "도움말수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    alert(getMessageParam("MSG-A002", "도움말수정"));
    alert(trs_Update.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Delete_OnSuccess = async function() {
    alert(getMessageParam("MSG-A001", "도움말삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    alert(getMessageParam("MSG-A002", "도움말삭제"));
    alert(trs_Delete.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.value;
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
    file_name.value = inf_find.Value;
    if (inf_find.Value == "") {
        file_name.value = filenm;
    }
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};

	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.topmenusearch_OnFilter = function(row) {
    f1 = topmenusearch.getCellData(row, "MENU_NM");
    if (f1.indexOf(cmb_QuickMenu_scren.getText()) != -1) {
        return true;
    } else {
        return false;
    }
};
scwin.cmb_QuickMenu_scren_OnCloseUp = function() {
    var selval = cmb_QuickMenu_scren.getText();
    if (selval != "화면명검색") {
        e = selval.split("_");
        if (e.length > 1) {
            cmb_QuickMenu_scren.setSelectedIndex(-1);
            ipt_scren_id.setValue(e[1].toString());
            ipt_scren_nm.setValue(e[0].toString());
        }
    }
};
scwin.cmb_QuickMenu_scren_OnKeyDown = function(keycode) {
    if (keycode == '13') {
        scwin.fn_topmenusearchEnter();
    }
};
scwin.file_OnClick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.gform_onload = function() {
    showObj(ipt_scren_id_2, false);
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

	//----W-Craft WebSquare 변환 확인: getContnId----//
    getContnId = $c.frame.path("../").fn_getContnId;

	//----W-Craft WebSquare 변환 확인: getContnId----//
    scwin.contnId = getContnId();
    if (scwin.contnId != "input") {
        scwin.fn_single_read();
        dts_fileList.insertRow();
        dts_fileList.setCellData(1, "fileInfo", dts_NoticeContentSingle.getCellData(1, "SAVE_FILE_NM"));
        txb_ATTACH_FILE_NM.setValue(dts_NoticeContentSingle.getCellData(1, "SAVE_FILE_NM"));
        MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
        MxDataSet_code1.reset();
        scwin.fn_code1_sync();
        var cb_system_gbn_idx = $c.cp.getNameValueRow(MxDataSet_code1, "CD_VAL", dts_NoticeContentSingle.getCellData(1, "NOTI_OBJ_SYS_TP_CD"));
        //var cb_system_gbn_idx = cb_system_gbn.IndexOfColumn("value", dts_NoticeContentSingle.NameString(1,"NOTI_OBJ_SYS_TP_CD"));
        //cb_system_gbn.Index = cb_system_gbn_idx;
        cb_system_gbn.setSelectedIndex((cb_system_gbn_idx - 1));
        showObj(cmb_QuickMenu_scren, false);
        cb_system_gbn.setDisabled(true);
        showObj(checkbox_1, false);
    } else {
        cb_system_gbn.setDisabled(false);
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileList.insertRow();
        scwin.fn_SetIrInfoHeader();
        showObj(btn_delete, false);

        //메뉴리스트 조회
        topmenusearch.dataid = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=topmenu";

	//----W-Craft WebSquare 변환 확인: reset----//
        topmenusearch.reset(); //2008-06-30 추가

        dts_menu.dataid = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=topmenu";

	//----W-Craft WebSquare 변환 확인: reset----//
        dts_menu.reset();
        //fn_list_menu();	
        userName.setValue(js_emp_nm);
        //cb_system_gbn.ResetData(); 

        MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
        MxDataSet_code1.reset();
        scwin.fn_code1_sync();
    }
    cmb_QuickMenu_scren.setSelectedIndex(-1);
};
scwin.cb_system_gbn_OnSelChange = function() {
    scwin.fn_list_menu();
};
scwin.checkbox_1_onclick = function() {
    if (checkbox_1.checked) {
        showObj(ipt_scren_id_2, true);
        showObj(cmb_QuickMenu_scren, false);
        showObj(ipt_scren_nm, false);
        showObj(ipt_scren_id, false);
    } else {
        showObj(ipt_scren_id_2, false);
        showObj(cmb_QuickMenu_scren, true);
        showObj(ipt_scren_nm, true);
        showObj(ipt_scren_id, true);
    }
};
